#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="${REPO_DIR:-"$(cd "$SCRIPT_DIR/../../.." && pwd)"}"
cd "$REPO_DIR"

GPUS_PER_NODE="${GPUS_PER_NODE:-8}"
# Baseline 12x8 A4 shape after the pipeline warmup residency audit:
# TP8 x CP4 keeps the full model on each data-parallel replica with Megatron
# FSDP sharding params/grads/optimizer state across DP=3. PP is kept at 1
# because every tested 32k DSA/HISA VPP/PP warmup shape OOMed before steady
# state, while this no-PP shape completed cleanly.
TP="${TP:-8}"
PP="${PP:-1}"
CP="${CP:-4}"
EP="${EP:-8}"
ETP="${ETP:-1}"
STRICT_ALL_NODES="${STRICT_ALL_NODES:-1}"
MAX_NODES="${MAX_NODES:-12}"

MODEL_PARALLEL_SIZE=$((TP * PP * CP))
EXPERT_MODEL_PARALLEL_SIZE=$((ETP * EP * PP))

names=()
ips=()
if [[ -n "${SLURM_JOB_NODELIST:-}" && "${FORCE_GCLOUD_DISCOVERY:-0}" != "1" ]]; then
  mapfile -t names < <(scontrol show hostnames "$SLURM_JOB_NODELIST")
  for name in "${names[@]}"; do
    ip="$(scontrol show node "$name" | awk '{for (i=1; i<=NF; i++) if ($i ~ /^NodeAddr=/) {sub(/^NodeAddr=/, "", $i); print $i; exit}}')"
    ips+=("${ip:-$name}")
  done
else
  mapfile -t rows < <(OUTPUT=csv "$SCRIPT_DIR/discover_nodes.sh" | tail -n +2)
  if (( ${#rows[@]} == 0 )); then
    echo "No running nodes matched INSTANCE_REGEX=${INSTANCE_REGEX:-^instance-group-1-} in ZONE=${ZONE:-us-east1-b}" >&2
    exit 2
  fi
  for row in "${rows[@]}"; do
    IFS=, read -r _rank name internal_ip _nat_ip <<<"$row"
    names+=("$name")
    ips+=("$internal_ip")
  done
fi

discovered_count="${#names[@]}"
if [[ -n "$MAX_NODES" ]]; then
  use_count="$MAX_NODES"
  if (( use_count > discovered_count )); then
    echo "MAX_NODES=$MAX_NODES exceeds discovered node count $discovered_count" >&2
    exit 2
  fi
else
  use_count="$discovered_count"
fi

while (( use_count > 0 )); do
  world_size=$((use_count * GPUS_PER_NODE))
  if (( world_size % MODEL_PARALLEL_SIZE == 0 && world_size % EXPERT_MODEL_PARALLEL_SIZE == 0 )); then
    break
  fi

  if [[ "$STRICT_ALL_NODES" == "1" || -n "$MAX_NODES" ]]; then
    cat >&2 <<EOF
Invalid distributed shape:
  nodes=$use_count gpus_per_node=$GPUS_PER_NODE world_size=$world_size
  TP=$TP PP=$PP CP=$CP EP=$EP ETP=$ETP
  required: world_size divisible by $MODEL_PARALLEL_SIZE and $EXPERT_MODEL_PARALLEL_SIZE
EOF
    exit 2
  fi

  use_count=$((use_count - 1))
done

if (( use_count == 0 )); then
  echo "Could not select a valid node count for the requested shape" >&2
  exit 2
fi

world_size=$((use_count * GPUS_PER_NODE))
dp=$((world_size / MODEL_PARALLEL_SIZE))
expert_dp=$((world_size / EXPERT_MODEL_PARALLEL_SIZE))

host_short="${HOSTNAME_SHORT:-$(hostname -s)}"
node_rank="${NODE_RANK:-}"
if [[ -z "$node_rank" ]]; then
  for idx in $(seq 0 $((use_count - 1))); do
    if [[ "${names[$idx]}" == "$host_short" ]]; then
      node_rank="$idx"
      break
    fi
  done
fi

if [[ -z "$node_rank" ]]; then
  cat >&2 <<EOF
This host ($host_short) is not in the selected node set.
Selected nodes:
$(for idx in $(seq 0 $((use_count - 1))); do printf "  %s %s %s\n" "$idx" "${names[$idx]}" "${ips[$idx]}"; done)
EOF
  exit 2
fi

MICRO_BATCH_SIZE="${MICRO_BATCH_SIZE:-1}"
# MBS=1 was the first stable 32k no-PP shape. Keep grad accumulation modest by
# default; larger values are mainly an optimizer/checkpoint amortization knob,
# not a memory fix.
GRAD_ACCUM_STEPS="${GRAD_ACCUM_STEPS:-4}"
GLOBAL_BATCH_SIZE="${GLOBAL_BATCH_SIZE:-$((MICRO_BATCH_SIZE * dp * GRAD_ACCUM_STEPS))}"
if (( GLOBAL_BATCH_SIZE % (MICRO_BATCH_SIZE * dp) != 0 )); then
  echo "GLOBAL_BATCH_SIZE=$GLOBAL_BATCH_SIZE must be divisible by MICRO_BATCH_SIZE*DP=$((MICRO_BATCH_SIZE * dp))" >&2
  exit 2
fi
NUM_MICROBATCHES=$((GLOBAL_BATCH_SIZE / (MICRO_BATCH_SIZE * dp)))

if (( discovered_count != use_count )); then
  echo "Discovered $discovered_count nodes; selected $use_count for this shape." >&2
  echo "Skipped nodes:" >&2
  for idx in $(seq "$use_count" $((discovered_count - 1))); do
    printf "  %s %s\n" "${names[$idx]}" "${ips[$idx]}" >&2
  done
fi

export NNODES="$use_count"
export GPUS_PER_NODE
export WORLD_SIZE="$world_size"
export NODE_RANK="$node_rank"
export MASTER_ADDR="${MASTER_ADDR:-${ips[0]}}"
export MASTER_PORT="${MASTER_PORT:-29673}"
export TP PP CP EP ETP
export ENABLE_VPP="${ENABLE_VPP:-0}"
export VPP_SIZE="${VPP_SIZE:-2}"
export USE_TP_PP_DP_MAPPING="${USE_TP_PP_DP_MAPPING:-1}"
if [[ "$ENABLE_VPP" == "1" && "${ALLOW_VPP_OOM_EXPERIMENT:-0}" != "1" ]]; then
  cat >&2 <<EOF
VPP is disabled for the current 32k DSA/HISA fleet profile.
The PP15/VPP2 and PP5/VPP experiments OOMed from pipeline warmup activation
residency before useful 1F1B steady state. Use plain PP unless intentionally
running a short OOM experiment with ALLOW_VPP_OOM_EXPERIMENT=1.
EOF
  exit 2
fi
if [[ "$ENABLE_VPP" == "1" && "$NUM_MICROBATCHES" -lt "$PP" ]]; then
  cat >&2 <<EOF
Invalid VPP batch shape:
  PP=$PP VPP_SIZE=$VPP_SIZE microbatches=$NUM_MICROBATCHES
  VPP interleaving requires microbatches >= PP.
  At MBS=$MICRO_BATCH_SIZE and DP=$dp, GLOBAL_BATCH_SIZE must be at least $((MICRO_BATCH_SIZE * dp * PP)).
EOF
  exit 2
fi
if [[ -z "${OVERLAP_P2P_COMM_WARMUP_FLUSH:-}" ]]; then
  if [[ "$ENABLE_VPP" == "1" ]]; then
    OVERLAP_P2P_COMM_WARMUP_FLUSH=1
  else
    OVERLAP_P2P_COMM_WARMUP_FLUSH=0
  fi
fi
export OVERLAP_P2P_COMM_WARMUP_FLUSH
if [[ -z "${PIPELINE_MODEL_PARALLEL_LAYOUT:-}" ]]; then
  if [[ "$PP" -eq 15 && "$ENABLE_VPP" == "1" && "$VPP_SIZE" == "2" ]]; then
    # PP15/VPP2/DP1: one TP4 x CP2 pipeline rank per A4 node. Each physical
    # PP rank owns four decoder layers except the middle rank, which owns five.
    PIPELINE_MODEL_PARALLEL_LAYOUT="Et*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*2|t*3|t*2|t*2|t*2|t*2|t*2|t*2|t*2L"
  elif [[ "$PP" -eq 15 && "$ENABLE_VPP" == "1" ]]; then
    echo "Unsupported VPP_SIZE=$VPP_SIZE for PP=$PP; expected 2" >&2
    exit 2
  elif [[ "$PP" -eq 15 ]]; then
    PIPELINE_MODEL_PARALLEL_LAYOUT="Et*4|t*4|t*4|t*4|t*4|t*4|t*4|t*5|t*4|t*4|t*4|t*4|t*4|t*4|t*4L"
  elif [[ "$PP" -eq 5 && "$ENABLE_VPP" == "1" && "$VPP_SIZE" == "4" ]]; then
    # PP5/VPP4 maximizes bubble reduction but keeps many 32k MoE activations
    # resident during warmup; leave it opt-in until the smaller layout is stable.
    PIPELINE_MODEL_PARALLEL_LAYOUT="Et*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*3|t*4|t*3|t*3|t*3|t*3L"
  elif [[ "$PP" -eq 5 && "$ENABLE_VPP" == "1" && "$VPP_SIZE" == "2" ]]; then
    # PP5/VPP2 with a memory-skewed 11/12/12/13/13 physical layer balance.
    # The uniform-ish 13/12/12/12/12 layout OOMed on PP0 during the full VPP
    # forward queue; later PP stages had substantially more memory headroom.
    PIPELINE_MODEL_PARALLEL_LAYOUT="Et*6|t*6|t*6|t*6|t*7|t*5|t*6|t*6|t*7|t*6L"
  elif [[ "$PP" -eq 5 && "$ENABLE_VPP" == "1" ]]; then
    echo "Unsupported VPP_SIZE=$VPP_SIZE for PP=$PP; expected 2 or 4" >&2
    exit 2
  elif [[ "$PP" -eq 5 ]]; then
    PIPELINE_MODEL_PARALLEL_LAYOUT="Et*13|t*12|t*12|t*12|t*12L"
  elif [[ "$PP" -eq 4 ]]; then
    # Plain PP4 trial for the FSDP/EP shape. Keep stage 0 and the loss stage
    # slightly lighter while PP absorbs layer residency and lets us reduce TP.
    PIPELINE_MODEL_PARALLEL_LAYOUT="Et*14|t*16|t*16|t*15L"
  fi
fi
export PIPELINE_MODEL_PARALLEL_LAYOUT="${PIPELINE_MODEL_PARALLEL_LAYOUT:-}"
INFERRED_VPP_SIZE="none"
if [[ -n "${PIPELINE_MODEL_PARALLEL_LAYOUT:-}" ]]; then
  layout_without_pipes="${PIPELINE_MODEL_PARALLEL_LAYOUT//|/}"
  layout_stage_count=$(( ${#PIPELINE_MODEL_PARALLEL_LAYOUT} - ${#layout_without_pipes} + 1 ))
  if (( PP > 0 && layout_stage_count % PP == 0 )); then
    INFERRED_VPP_SIZE=$(( layout_stage_count / PP ))
  else
    INFERRED_VPP_SIZE="invalid:${layout_stage_count}/PP${PP}"
  fi
fi
export MICRO_BATCH_SIZE GLOBAL_BATCH_SIZE
export SEQ_LENGTH="${SEQ_LENGTH:-32768}"
export DSA_INDEXER_TOPK="${DSA_INDEXER_TOPK:-1024}"
export DSA_INDEXER_LOSS_COEFF="${DSA_INDEXER_LOSS_COEFF:-0.1}"
export MEGATRON_DSA_INDEXER_AUX_LOSS_SCALE_MODE="${MEGATRON_DSA_INDEXER_AUX_LOSS_SCALE_MODE:-token_mean}"
export TRAIN_TOKEN_TARGET="${TRAIN_TOKEN_TARGET:-24691703808}"
export LR="${LR:-5.0e-6}"
export MIN_LR="${MIN_LR:-$LR}"
export LR_WARMUP_SAMPLES="${LR_WARMUP_SAMPLES:-0}"
export NUM_WORKERS="${NUM_WORKERS:-16}"
export EMPTY_UNUSED_MEMORY_LEVEL="${EMPTY_UNUSED_MEMORY_LEVEL:-0}"
export MEGATRON_DISABLE_JIT_FUSER="${MEGATRON_DISABLE_JIT_FUSER:-0}"
export MEGATRON_RUN_STATS_LOG="${MEGATRON_RUN_STATS_LOG:-1}"
export GRAD_REDUCE_IN_BF16="${GRAD_REDUCE_IN_BF16:-1}"
export MEGATRON_SKIP_NONFINITE_GRAD_NORM="${MEGATRON_SKIP_NONFINITE_GRAD_NORM:-1}"
export MEGATRON_NONFINITE_GRAD_OWNERSHIP="${MEGATRON_NONFINITE_GRAD_OWNERSHIP:-1}"
export MEGATRON_GRAD_OWNERSHIP_NONFINITE_PARAMS="${MEGATRON_GRAD_OWNERSHIP_NONFINITE_PARAMS:-16}"
export CALCULATE_PER_TOKEN_LOSS="${CALCULATE_PER_TOKEN_LOSS:-1}"
export SFT_FINETUNE="${SFT_FINETUNE:-1}"
export OVERLAP_PARAM_GATHER="${OVERLAP_PARAM_GATHER:-1}"
export USE_MEGATRON_FSDP="${USE_MEGATRON_FSDP:-1}"
export DATA_PARALLEL_SHARDING_STRATEGY="${DATA_PARALLEL_SHARDING_STRATEGY:-optim_grads_params}"
export FSDP_INIT_MODEL_WITH_META_DEVICE="${FSDP_INIT_MODEL_WITH_META_DEVICE:-1}"
export FSDP_USE_NCCL_UB="${FSDP_USE_NCCL_UB:-0}"
export FSDP_DOUBLE_BUFFER="${FSDP_DOUBLE_BUFFER:-0}"
export FSDP_CREATE_ALL_GATHER_GROUP="${FSDP_CREATE_ALL_GATHER_GROUP:-0}"
export FSDP_MANUAL_REGISTRATION="${FSDP_MANUAL_REGISTRATION:-0}"
export FSDP_DISABLE_SYMMETRIC_REGISTRATION="${FSDP_DISABLE_SYMMETRIC_REGISTRATION:-0}"
export MEGATRON_FSDP_FLUSH_READY_BUCKETS_ON_RESET="${MEGATRON_FSDP_FLUSH_READY_BUCKETS_ON_RESET:-1}"
export MEGATRON_FSDP_LOG_READY_BUCKET_FLUSH="${MEGATRON_FSDP_LOG_READY_BUCKET_FLUSH:-0}"
export OVERLAP_MOE_EXPERT_PARALLEL_COMM="${OVERLAP_MOE_EXPERT_PARALLEL_COMM:-0}"
if [[ "$USE_MEGATRON_FSDP" == "1" ]]; then
  export CUDA_DEVICE_MAX_CONNECTIONS="${CUDA_DEVICE_MAX_CONNECTIONS:-8}"
elif [[ "$OVERLAP_MOE_EXPERT_PARALLEL_COMM" == "1" ]]; then
  export CUDA_DEVICE_MAX_CONNECTIONS="${CUDA_DEVICE_MAX_CONNECTIONS:-32}"
else
  export CUDA_DEVICE_MAX_CONNECTIONS="${CUDA_DEVICE_MAX_CONNECTIONS:-1}"
fi
if [[ "$USE_MEGATRON_FSDP" == "1" && "$CUDA_DEVICE_MAX_CONNECTIONS" == "1" ]]; then
  echo "USE_MEGATRON_FSDP=1 requires CUDA_DEVICE_MAX_CONNECTIONS to be unset or greater than 1" >&2
  exit 1
fi
export HIGH_PRIORITY_A2A_COMM_STREAM="${HIGH_PRIORITY_A2A_COMM_STREAM:-0}"
export EP_OVERLAP_EARLY_ATTN_MEMORY_RELEASE="${EP_OVERLAP_EARLY_ATTN_MEMORY_RELEASE:-0}"
export DELAY_WGRAD_COMPUTE="${DELAY_WGRAD_COMPUTE:-0}"
export OVERLAP_DISPATCH_BACKWARD_WITH_EXPERTS_WGRAD="${OVERLAP_DISPATCH_BACKWARD_WITH_EXPERTS_WGRAD:-0}"
export MOE_HYBRIDEP_NUM_SMS_PREPROCESSING="${MOE_HYBRIDEP_NUM_SMS_PREPROCESSING:-}"
export LOAD_CKPT="${LOAD_CKPT:-$HOME/checkpoints/deepseek_v32_reap_spinquant_actkv_nvfp4_megatron_tp8_pp1_ep8}"
export SAVE_CKPT="${SAVE_CKPT:-$HOME/checkpoints/sft_deepseek_v32_reap_spinquant_actkv_nvfp4_tp${TP}_pp${PP}_cp${CP}_ep${EP}}"
export DATA_PATH="${DATA_PATH:-$HOME/data/sft/blaise-sft-training-mix/blaise-sft-training-mix-full.jsonl}"
export DATALOADER_TYPE="${DATALOADER_TYPE:-cyclic}"
export MEGATRON_SFT_SHUFFLE_ROWS="${MEGATRON_SFT_SHUFFLE_ROWS:-1}"
export MEGATRON_SFT_SHUFFLE_SEED="${MEGATRON_SFT_SHUFFLE_SEED:-1234}"
export MEGATRON_SFT_SHUFFLE_BUILD_IF_MISSING="${MEGATRON_SFT_SHUFFLE_BUILD_IF_MISSING:-1}"
export MODEL_ID="${MODEL_ID:-BlaiseAI/DeepSeek-V3.2-REAP-345B-SpinQuant-ActKV-NVFP4}"
export TOKENIZER_MODEL="${TOKENIZER_MODEL:-$MODEL_ID}"
export MEGATRON_SFT_MASK_SYNTHETIC_TOOL_CALLS="${MEGATRON_SFT_MASK_SYNTHETIC_TOOL_CALLS:-1}"
export SAVE_INTERVAL="${SAVE_INTERVAL:-5}"
# Megatron deletes the previous checkpoint only when that previous iteration is
# not itself a retain interval. Use a large multiple of SAVE_INTERVAL so the
# production run keeps only the most recent ordinary checkpoint on local disk.
export SAVE_RETAIN_INTERVAL="${SAVE_RETAIN_INTERVAL:-1000000}"
export CKPT_FULLY_PARALLEL_LOAD="${CKPT_FULLY_PARALLEL_LOAD:-1}"
export CKPT_FULLY_PARALLEL_LOAD_PROCESS_GROUP="${CKPT_FULLY_PARALLEL_LOAD_PROCESS_GROUP:-dp}"
export CKPT_FULLY_PARALLEL_LOAD_EXCHANGE_ALGO="${CKPT_FULLY_PARALLEL_LOAD_EXCHANGE_ALGO:-broadcast}"
export WANDB_ENTITY="${WANDB_ENTITY:-blaise-ai}"
export WANDB_PROJECT="${WANDB_PROJECT:-corsaire-1}"
export WANDB_EXP_NAME="${WANDB_EXP_NAME:-corsaire-1-research-preview}"
