# Offline is the default for every training run. To intentionally publish live,
# set both WANDB_FORCE_OFFLINE=0 and WANDB_MODE=online at launch.
export WANDB_FORCE_OFFLINE="${WANDB_FORCE_OFFLINE:-1}"
if [[ "$WANDB_FORCE_OFFLINE" == "1" ]]; then
  export WANDB_MODE=offline
else
  export WANDB_MODE="${WANDB_MODE:-offline}"
fi
export ENABLE_ONE_LOGGER="${ENABLE_ONE_LOGGER:-1}"
export ONE_LOGGER_PROJECT="${ONE_LOGGER_PROJECT:-${WANDB_PROJECT:-megatron-lm}}"
export ONE_LOGGER_RUN_NAME="${ONE_LOGGER_RUN_NAME:-${WANDB_EXP_NAME:-gcp-a4-deepseek-sft}-${SLURM_JOB_ID:-manual}}"
export ONE_LOGGER_DIR="${ONE_LOGGER_DIR:-$HOME/logs/one_logger}"
export ZCC_RUN_NAME="${ZCC_RUN_NAME:-$WANDB_EXP_NAME}"
export ENABLE_ZCC="${ENABLE_ZCC:-1}"
export ZCC_WORKERS_NUM="${ZCC_WORKERS_NUM:-8}"
export ZCC_FLASH_DEVICE="${ZCC_FLASH_DEVICE:-/dev/shm/megatron_zcc/$ZCC_RUN_NAME}"
export ZCC_DURABLE_DIR="${ZCC_DURABLE_DIR:-$SAVE_CKPT/zcc/$ZCC_RUN_NAME}"
export ZCC_DURABLE_INTERVAL="${ZCC_DURABLE_INTERVAL:-1}"
export ZCC_COMPRESS="${ZCC_COMPRESS:-zstd:1}"
export ZCC_RETAIN_LATEST="${ZCC_RETAIN_LATEST:-2}"
export HF_UPLOAD_CHECKPOINTS="${HF_UPLOAD_CHECKPOINTS:-0}"
export HF_REPO_ID="${HF_REPO_ID:-BlaiseAI/corsaire-1-research-preview}"
export HF_UPLOAD_FOLDER_PREFIX="${HF_UPLOAD_FOLDER_PREFIX:-corsaire-1-research-preview}"
export HF_UPLOAD_INTERVAL="${HF_UPLOAD_INTERVAL:-500}"
export HF_UPLOAD_RETAIN="${HF_UPLOAD_RETAIN:-1}"
export HF_UPLOAD_STABLE_SECONDS="${HF_UPLOAD_STABLE_SECONDS:-180}"
export HF_UPLOAD_POLL_SECONDS="${HF_UPLOAD_POLL_SECONDS:-60}"
export HF_UPLOAD_FINALIZE_TIMEOUT_SECONDS="${HF_UPLOAD_FINALIZE_TIMEOUT_SECONDS:-7200}"
export HF_UPLOAD_PRIVATE="${HF_UPLOAD_PRIVATE:-1}"
export HF_UPLOAD_RETENTION_NODE_RANK="${HF_UPLOAD_RETENTION_NODE_RANK:-0}"
export HF_UPLOAD_EXPECTED_NODES="${HF_UPLOAD_EXPECTED_NODES:-$NNODES}"
export TORCH_EXTENSIONS_DIR="${TORCH_EXTENSIONS_DIR:-/tmp/torch_extensions_${USER:-sjpat}_${SLURM_JOB_ID:-manual}}"
mkdir -p "$TORCH_EXTENSIONS_DIR"

if [[ "${PROFILE_RUN:-0}" == "1" ]]; then
  export PROFILE_HEAVY="${PROFILE_HEAVY:-1}"
  export ENABLE_PROFILING="${ENABLE_PROFILING:-1}"
  export USE_PYTORCH_PROFILER="${USE_PYTORCH_PROFILER:-1}"
  if [[ "$PROFILE_HEAVY" == "1" ]]; then
    export PYTORCH_PROFILER_COLLECT_SHAPES="${PYTORCH_PROFILER_COLLECT_SHAPES:-1}"
    export PYTORCH_PROFILER_COLLECT_CALLSTACK="${PYTORCH_PROFILER_COLLECT_CALLSTACK:-1}"
    export PYTORCH_PROFILER_PROFILE_MEMORY="${PYTORCH_PROFILER_PROFILE_MEMORY:-1}"
    export PYTORCH_PROFILER_WITH_FLOPS="${PYTORCH_PROFILER_WITH_FLOPS:-1}"
    export PYTORCH_PROFILER_WITH_MODULES="${PYTORCH_PROFILER_WITH_MODULES:-1}"
  else
    export PYTORCH_PROFILER_COLLECT_SHAPES="${PYTORCH_PROFILER_COLLECT_SHAPES:-0}"
    export PYTORCH_PROFILER_COLLECT_CALLSTACK="${PYTORCH_PROFILER_COLLECT_CALLSTACK:-0}"
    export PYTORCH_PROFILER_PROFILE_MEMORY="${PYTORCH_PROFILER_PROFILE_MEMORY:-0}"
    export PYTORCH_PROFILER_WITH_FLOPS="${PYTORCH_PROFILER_WITH_FLOPS:-0}"
    export PYTORCH_PROFILER_WITH_MODULES="${PYTORCH_PROFILER_WITH_MODULES:-0}"
  fi
  export PROFILE_STEP_START="${PROFILE_STEP_START:-1}"
  export PROFILE_STEP_END="${PROFILE_STEP_END:-3}"
  export MEGATRON_FINE_PROFILE="${MEGATRON_FINE_PROFILE:-1}"
  export MEGATRON_FINE_PROFILE_TIMERS="${MEGATRON_FINE_PROFILE_TIMERS:-1}"
  export MEGATRON_FINE_PROFILE_TIMER_TOP_N="${MEGATRON_FINE_PROFILE_TIMER_TOP_N:-160}"
  export MEGATRON_FINE_PROFILE_TIMER_FILTER="${MEGATRON_FINE_PROFILE_TIMER_FILTER:-*}"
  export MEGATRON_FINE_PROFILE_RANKS="${MEGATRON_FINE_PROFILE_RANKS:-${PROFILE_RANKS:-0,7,88,95}}"
  export PROFILE_RANKS="${PROFILE_RANKS:-$MEGATRON_FINE_PROFILE_RANKS}"
  export TENSORBOARD_LOGS_PATH="${TENSORBOARD_LOGS_PATH:-$HOME/tensorboard_logs/sft_deepseek_v32_reap_nvfp4/profiles/${SLURM_JOB_ID:-manual}/tb}"
