  export DISABLE_SAVE="${DISABLE_SAVE:-1}"
  export ENABLE_ZCC="${PROFILE_ENABLE_ZCC:-0}"
  export HF_UPLOAD_CHECKPOINTS="${PROFILE_HF_UPLOAD_CHECKPOINTS:-0}"
