    export WANDB_PROJECT=""
  fi
fi

if [[ "${LOSS_AUTOPSY:-0}" == "1" ]]; then
  # This mode is intentionally intrusive and should only be used for short
  # semantic/loss probes. It trades throughput and log volume for attribution:
  # token supervision, per-token loss tails, router/DSA state, every grad
  # accumulation stage we have hooks for, and optimizer/flashopt numeric probes.
  export ENABLE_TRAINING_DEBUG=1
  export LOG_INTERVAL="${LOG_INTERVAL:-1}"
  export TENSORBOARD_LOG_INTERVAL="${TENSORBOARD_LOG_INTERVAL:-1}"
