ensure_patched_deepep() {
  if [[ "${MEGATRON_DEEPEP_EXPERT_MAJOR_DISPATCH:-0}" != "1" && "${MEGATRON_DEEPEP_EXPERT_MAJOR_COMBINE:-0}" != "1" ]]; then
    return
  fi

  if uv run --no-sync python - <<'PY' >/dev/null 2>&1
import deep_ep
missing = [
    name
    for name in ("dispatch_expert_major", "combine_expert_major")
    if not hasattr(deep_ep.Buffer, name)
]
if missing:
    raise SystemExit(f"deep_ep.Buffer missing patched APIs: {missing}")
PY
  then
    return
  fi

  local wheel="${DEEP_EP_WHEEL:-$REPO_DIR/handoff/gcp-a4/wheelhouse/deep_ep-1.2.1+9af0e0d-cp312-cp312-linux_x86_64.whl}"
  if [[ ! -f "$wheel" ]]; then
    echo "Patched DeepEP wheel is required but missing: $wheel" >&2
    exit 2
  fi

  echo "Installing patched DeepEP wheel on $(hostname -s): $wheel" >&2
  uv pip install --force-reinstall "$wheel" >&2
  uv run --no-sync python - <<'PY' >&2
import deep_ep
missing = [
    name
    for name in ("dispatch_expert_major", "combine_expert_major")
    if not hasattr(deep_ep.Buffer, name)
]
if missing:
    raise SystemExit(f"patched DeepEP install failed; missing APIs: {missing}")
print("patched_deepep_ok", deep_ep.__file__)
PY
}

ensure_patched_deepep

