if [[ "$FASTPATH_STRICT" == "1" ]]; then
  fastpath_errors=()
  require_fastpath_eq() {
    local name="$1"
    local expected="$2"
    local actual="${!name:-}"
    if [[ "$actual" != "$expected" ]]; then
      fastpath_errors+=("$name=$actual expected $expected")
    fi
  }
  require_fastpath_nonchunked_or_zero() {
    local name="$1"
    local local_seq="$2"
    local actual="${!name:-}"
    if [[ ! "$actual" =~ ^[0-9]+$ ]]; then
      fastpath_errors+=("$name=$actual expected integer 0 or >= $local_seq")
      return
    fi
    if (( actual > 0 && actual < local_seq )); then
      fastpath_errors+=("$name=$actual chunks local sequence length $local_seq")
    fi
  }
  require_fastpath_positive_integer() {
    local name="$1"
    local actual="${!name:-}"
    if [[ ! "$actual" =~ ^[0-9]+$ ]] || (( actual <= 0 )); then
      fastpath_errors+=("$name=$actual expected positive integer")
    fi
  }
  require_fastpath_min_integer() {
    local name="$1"
    local min_value="$2"
    local actual="${!name:-}"
    if [[ ! "$actual" =~ ^[0-9]+$ ]] || (( actual < min_value )); then
      fastpath_errors+=("$name=$actual expected integer >= $min_value")
    fi
  }
  require_fastpath_eq USE_STREAMBP 0
  require_fastpath_eq MEGATRON_USE_STREAMBP 0
  require_fastpath_eq STREAMBP_MOE_CHUNK_FORWARD 0
  require_fastpath_eq STREAMBP_MOE_MLP_CHUNKS 1
