  if [[ "${FINE_GRAINED_ACTIVATION_OFFLOADING:-0}" == "1" ]]; then
    require_fastpath_eq OFFLOAD_MODULES "expert_fc1"
    require_fastpath_eq NVTE_CPU_OFFLOAD_V1 1
  else
    require_fastpath_eq FINE_GRAINED_ACTIVATION_OFFLOADING 0
    require_fastpath_eq OFFLOAD_MODULES ""
  fi
  require_fastpath_eq MEGATRON_TEMP_ACTIVATION_OFFLOAD 0
  require_fastpath_eq MEGATRON_TEMP_ACTIVATION_OFFLOAD_MODULES ""
  require_fastpath_eq MEGATRON_TEMP_ACTIVATION_OFFLOAD_MIN_MB 0
  require_fastpath_eq MEGATRON_TEMP_ACTIVATION_OFFLOAD_EMPTY_CACHE 0
