  require_fastpath_eq MEGATRON_DEEPEP_COMPACT_CUDA_UNPERMUTE 1
  require_fastpath_eq MEGATRON_DEEPEP_EXPERT_MAJOR_DISPATCH 1
  require_fastpath_eq MEGATRON_DEEPEP_EXPERT_MAJOR_COMBINE 0
