HF_UPLOAD_PID=""
cleanup_hf_upload() {
  if [[ -n "$HF_UPLOAD_PID" ]]; then
    kill "$HF_UPLOAD_PID" 2>/dev/null || true
  fi
}

if [[ "$HF_UPLOAD_CHECKPOINTS" == "1" && "${DISABLE_SAVE:-0}" != "1" && "${DRY_RUN:-0}" != "1" ]]; then
  mkdir -p "$SAVE_CKPT/hf_upload_logs"
  printf -v node_rank_padded "%03d" "$NODE_RANK"
  HF_PRIVATE_ARG=()
  if [[ "$HF_UPLOAD_PRIVATE" == "1" ]]; then
    HF_PRIVATE_ARG=(--private)
  fi
  HF_RETENTION_ARG=()
  if [[ "$NODE_RANK" == "$HF_UPLOAD_RETENTION_NODE_RANK" ]]; then
    HF_RETENTION_ARG=(--retention-owner)
  fi
  echo "Starting HF checkpoint upload sidecar on node_rank=$NODE_RANK -> $HF_REPO_ID" >&2
  uv run --no-sync python tools/upload_mcore_checkpoints_to_hf.py \
    --checkpoint-root "$SAVE_CKPT" \
    --repo-id "$HF_REPO_ID" \
    --folder-prefix "$HF_UPLOAD_FOLDER_PREFIX" \
    --node-name "node${node_rank_padded}-$(hostname -s)" \
    --node-rank "$NODE_RANK" \
    --expected-nodes "$HF_UPLOAD_EXPECTED_NODES" \
    --upload-interval "$HF_UPLOAD_INTERVAL" \
    --retain "$HF_UPLOAD_RETAIN" \
    --stable-seconds "$HF_UPLOAD_STABLE_SECONDS" \
    --poll-seconds "$HF_UPLOAD_POLL_SECONDS" \
    --finalize-timeout-seconds "$HF_UPLOAD_FINALIZE_TIMEOUT_SECONDS" \
    "${HF_PRIVATE_ARG[@]}" \
    "${HF_RETENTION_ARG[@]}" \
    > "$SAVE_CKPT/hf_upload_logs/node${node_rank_padded}.log" 2>&1 &
  HF_UPLOAD_PID="$!"
  trap cleanup_hf_upload EXIT
fi

